func parentJobBlock() schema.SingleNestedBlock {
	return schema.SingleNestedBlock{
		Description: "The parent job of this job, if this job is a sub-job of another job by design (for example, a task defined within a DAG). Should be used on job events. It may also be used on run events when the specific run of the parent job is not known; if a ParentRunFacet is also present, it takes precedence.",
		Blocks: map[string]schema.Block{
			"job": schema.SingleNestedBlock{
				Attributes: map[string]schema.Attribute{
					"name":      optionalString("The unique name for that job within that namespace"),
					"namespace": optionalString("The namespace containing that job"),
				},
				Validators: requireFields(
					"name",
					"namespace",
				),
			},
			"root": schema.SingleNestedBlock{
				Blocks: map[string]schema.Block{
					"job": schema.SingleNestedBlock{
						Attributes: map[string]schema.Attribute{
							"name":      optionalString("The unique name for that job within that namespace"),
							"namespace": optionalString("The namespace containing that job"),
						},
						Validators: requireFields(
							"name",
							"namespace",
						),
					},
				},
				Validators: requireFields(
					"job",
				),
			},
		},
		Validators: requireFields(
			"job",
		),
	}
}

